import { Mail, ArrowUpRight } from "lucide-react";
import Link from "next/link";
import { cn } from "@/lib/utils";
export function Wordmark({
  className,
  markClassName,
}: { className?: string; markClassName?: string } = {}) {
  return (
    <Link
      href="/"
      className={cn(
        "inline-flex min-h-11 items-center gap-2 text-xl font-semibold tracking-tight",
        className,
      )}
      translate="no"
    >
      <span
        className={cn(
          "logo-mark [background:var(--logo-background)] text-[var(--logo-ink)] shadow-[0_8px_22px_color-mix(in_srgb,_var(--accent)_38%,_transparent)] grid place-items-center w-8 h-8 rounded-[10px]",
          markClassName,
        )}
      >
        <svg
          viewBox="0 0 64 64"
          fill="none"
          stroke="currentColor"
          strokeWidth={3}
          className="size-full"
          aria-hidden="true"
        >
          <rect x={13} y={20} width={38} height={26} rx={4} />
          <path d="m15 23 17 12 17-12" strokeLinejoin="round" />
        </svg>
      </span>
      mailloop
    </Link>
  );
}
export function PageHeading({
  eyebrow,
  title,
  description,
  action,
}: {
  eyebrow: string;
  title: string;
  description: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="mb-[22px] flex flex-wrap items-end justify-between gap-4">
      <div className="min-w-0">
        <p className="eyebrow mb-1 text-link">{eyebrow}</p>
        <h1 className="text-[34px] leading-tight">{title}</h1>
        <p className="mt-2 max-w-2xl text-sm leading-6 text-body">
          {description}
        </p>
      </div>
      {action}
    </div>
  );
}
export function EmptyState({
  title,
  description,
  href,
  link,
}: {
  title: string;
  description: string;
  href?: string;
  link?: string;
}) {
  return (
    <div className="panel px-6 py-16 text-center">
      <Mail className="mx-auto mb-4 size-6 text-body" aria-hidden="true" />
      <h2 className="text-xl font-semibold tracking-tight">{title}</h2>
      <p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-body">
        {description}
      </p>
      {href && (
        <Link
          href={href}
          className="mt-6 inline-flex min-h-11 items-center gap-2 text-sm font-medium text-link"
        >
          {link}
          <ArrowUpRight className="size-4" aria-hidden="true" />
        </Link>
      )}
    </div>
  );
}
export function Status({ status }: { status: string }) {
  const styles: Record<string, string> = {
    QUEUED:
      "status-queued text-[var(--status-warning-text)] [background:color-mix(in_srgb,_var(--queued)_15%,_transparent)]",
    SENT: "status-sent text-[var(--color-globals-color-48)] [background:color-mix(_in_srgb,_var(--color-globals-background-49)_14%,_transparent)] shadow-[inset_0_0_0_1px_color-mix(in_srgb,_var(--color-globals-success-12)_24%,_transparent)]",
    CANCELLED: "text-body bg-muted",
    FAILED:
      "status-failed text-[var(--status-error-text)] [background:color-mix(in_srgb,_var(--error)_15%,_transparent)]",
    REPLIED:
      "status-replied text-[var(--color-globals-color-51)] [background:color-mix(_in_srgb,_var(--color-globals-background-52)_14%,_transparent)] shadow-[inset_0_0_0_1px_color-mix(in_srgb,_var(--color-globals-replied-13)_24%,_transparent)]",
  };
  return (
    <span
      className={`status-pill inline-flex items-center gap-1.5 rounded-full py-1 px-[11px] text-[12px] font-semibold ${styles[status] ?? styles.QUEUED}`}
    >
      <span
        aria-hidden="true"
        className="status-dot size-1.5 rounded-full bg-current"
      />
      {status.charAt(0) + status.slice(1).toLowerCase()}
    </span>
  );
}
